    private static string S(JsonObject obj,string key,string fallback="")=>KnowledgeCorpus.Text(obj,key,fallback);
    internal static JsonObject Manifest(JsonObject args){var artifact=Data.Required(args,"artifact");if(args["bindings"] is not JsonArray{Count:<=1000} bindings)throw new ProcessingException("BINDINGS_REQUIRED");var dependencies=new JsonArray();foreach(var node in bindings){if(node is not JsonObject binding)throw new ProcessingException("BINDING_REQUIRED");if(S(binding,"artifact")!=artifact)continue;foreach(var key in new[]{"id","node","system","value_set","value_set_version"})Data.Required(binding,key);var dependency=new JsonObject();foreach(var key in new[]{"id","node","system","value_set","value_set_version","code_system_version","requirements"})if(binding[key] is not null)dependency[key]=binding[key]!.DeepClone();dependencies.Add(dependency);}return new JsonObject{["artifact"]=artifact,["terminology_dependencies"]=dependencies,["status"]="DECLARED_DEPENDENCIES",["generated_at"]=DateTimeOffset.UtcNow.ToString("O")};}
    private static JsonObject ValueSet(JsonObject set){foreach(var key in new[]{"id","system","version"})if(Data.Required(set,key).Length>2048)throw new ProcessingException("VALUE_SET_INVALID");if(!Uri.TryCreate(S(set,"system"),UriKind.Absolute,out var system)||system.UserInfo!=""||system.Scheme is not("http" or "https"))throw new ProcessingException("VALUE_SET_INVALID");var source=S(set,"source","local");if(source is not("local" or "external"))throw new ProcessingException("VALUE_SET_INVALID");if(source=="external"&&(!Uri.TryCreate(S(set,"canonical"),UriKind.Absolute,out var canonical)||canonical.UserInfo!=""||canonical.Scheme is not("http" or "https")))throw new ProcessingException("VALUE_SET_INVALID");
        if(set["code_system_version"] is not null&&S(set,"code_system_version").Length is <1 or >2048)throw new ProcessingException("VALUE_SET_INVALID");if(set["concepts"] is not(null or JsonArray{Count:<=5000}))throw new ProcessingException("VALUE_SET_INVALID");var codes=new HashSet<string>(StringComparer.Ordinal);
        foreach(var item in set["concepts"] as JsonArray??[]){if(item is not JsonObject concept||!codes.Add(Data.Required(concept,"code"))||concept["display"] is not JsonValue display||!display.TryGetValue<string>(out _))throw new ProcessingException("VALUE_SET_CONCEPT_INVALID");foreach(var flag in new[]{"inactive","abstract"})if(concept[flag] is not null&&(concept[flag] is not JsonValue boolean||!boolean.TryGetValue<bool>(out _)))throw new ProcessingException("VALUE_SET_CONCEPT_INVALID");
            if(concept["parents"] is not(null or JsonArray{Count:<=50}))throw new ProcessingException("VALUE_SET_PARENTS_INVALID");var parents=new HashSet<string>(StringComparer.Ordinal);foreach(var parent in concept["parents"] as JsonArray??[])if(parent is not JsonValue value||!value.TryGetValue<string>(out var text)||text.Length is <1 or >500||!parents.Add(text))throw new ProcessingException("VALUE_SET_PARENTS_INVALID");
