    internal static JsonObject Diff(JsonObject args){var before=ValueSet(args["before"] as JsonObject??throw new ProcessingException("VALUE_SET_REQUIRED"));var after=ValueSet(args["after"] as JsonObject??throw new ProcessingException("VALUE_SET_REQUIRED"));Dictionary<string,JsonObject> Concepts(JsonObject set)=>(set["concepts"] as JsonArray??[]).OfType<JsonObject>().ToDictionary(c=>S(c,"code"),StringComparer.Ordinal);var a=Concepts(before);var b=Concepts(after);JsonArray Copy(IEnumerable<JsonObject> values)=>new(values.Select(v=>(JsonNode)v.DeepClone()).ToArray());
        if(S(before,"system")!=S(after,"system"))return new JsonObject{["system_changed"]=true,["removed"]=Copy(a.Values),["added"]=Copy(b.Values),["review_required"]=true};
        var changed=new JsonArray();var inactive=new JsonArray();var replacements=new JsonArray();foreach(var(code,concept)in b){if(a.TryGetValue(code,out var old)&&!JsonNode.DeepEquals(old,concept))changed.Add(new JsonObject{["code"]=code,["before"]=old.DeepClone(),["after"]=concept.DeepClone()});if(concept["inactive"]?.GetValue<bool>()==true&&old?["inactive"]?.GetValue<bool>()!=true)inactive.Add(code);if(concept["replacement"] is not null)replacements.Add(new JsonObject{["code"]=code,["suggestion"]=concept["replacement"]!.DeepClone()});}
        JsonObject hierarchy;if(a.Count==0||b.Count==0||a.Values.Concat(b.Values).Any(c=>c["parents"] is null))hierarchy=new JsonObject{["status"]="NOT_COMPARABLE",["reason"]="Explicit parent relationships are required for every concept in both versions."};
        else{Dictionary<string,JsonObject> Edges(Dictionary<string,JsonObject> concepts){var edges=new Dictionary<string,JsonObject>(StringComparer.Ordinal);foreach(var(code,concept)in concepts)foreach(var parent in concept["parents"]!.AsArray())edges[Data.Canonical(new JsonArray(code,parent!.GetValue<string>()))]=new JsonObject{["child"]=code,["parent"]=parent.DeepClone()};return edges;}var oldEdges=Edges(a);var newEdges=Edges(b);hierarchy=new JsonObject{["status"]="COMPARED_DECLARED_RELATIONSHIPS",["added"]=Copy(newEdges.OrderBy(p=>p.Key,StringComparer.Ordinal).Where(p=>!oldEdges.ContainsKey(p.Key)).Select(p=>p.Value)),["removed"]=Copy(oldEdges.OrderBy(p=>p.Key,StringComparer.Ordinal).Where(p=>!newEdges.ContainsKey(p.Key)).Select(p=>p.Value)),["review_required"]=true,["scope"]="explicit_parent_edges_only"};}
        return new JsonObject{["system"]=before["system"]!.DeepClone(),["before_version"]=before["version"]!.DeepClone(),["after_version"]=after["version"]!.DeepClone(),["added"]=Copy(b.Where(p=>!a.ContainsKey(p.Key)).Select(p=>p.Value)),["removed"]=Copy(a.Where(p=>!b.ContainsKey(p.Key)).Select(p=>p.Value)),["changed"]=changed,["inactive"]=inactive,["replacements"]=replacements,["hierarchy"]=hierarchy,["review_required"]=true,["codes_replaced_automatically"]=false};
    }
    internal static async Task<JsonObject> Validate(JsonObject args,Func<string,JsonObject,CancellationToken,Task<JsonObject>> external,CancellationToken cancellation){var binding=args["binding"] as JsonObject??throw new ProcessingException("BINDING_REQUIRED");var set=ValueSet(args["valueSet"] as JsonObject??throw new ProcessingException("VALUE_SET_REQUIRED"));var model=Data.Required(args,"model");foreach(var key in new[]{"id","artifact","node","strength","value_set","value_set_version"})Data.Required(binding,key);if(!new[]{"REQUIRED","EXTENSIBLE","PREFERRED","EXAMPLE"}.Contains(S(binding,"strength")))throw new ProcessingException("BINDING_STRENGTH_INVALID");var errors=new JsonArray();if(S(binding,"value_set")!=S(set,"id")||S(binding,"value_set_version")!=S(set,"version"))errors.Add("VALUE_SET_REFERENCE_OR_VERSION_MISMATCH");
        var location=S(binding,"target_location");if(location!=""&&!Regex.IsMatch(location,"\\A/1(?:/[1-9][0-9]*)*\\z"))throw new ProcessingException("BINDING_LOCATION_INVALID");var xml=Imports.Xml(model);var targets=new JsonArray();void Walk(System.Xml.Linq.XElement node,string at){if((string?)node.Attribute("path")==S(binding,"node")&&(location==""||location==at))targets.Add(at);var index=0;foreach(var child in node.Elements())Walk(child,at+"/"+(++index));}if(xml.Root is not null)Walk(xml.Root,"/1");if(targets.Count>1)errors.Add("BINDING_TARGET_AMBIGUOUS");if(targets.Count==0)errors.Add("BINDING_TARGET_NOT_EXPLICIT_IN_TEMPLATE");
        if(binding["codes"] is not(null or JsonArray{Count:<=100}))throw new ProcessingException("BINDING_CODES_INVALID");var codes=binding["codes"] as JsonArray??[];var results=new JsonArray();var notExecuted=false;
        if(codes.Count==0&&S(set,"source","local")=="external"){var expanded=await external("terminology_expand",new JsonObject{["valueSet"]=set["canonical"]!.DeepClone(),["version"]=set["version"]!.DeepClone(),["count"]=1},cancellation);notExecuted=S(expanded,"status")!="VALIDATED";results.Add(expanded);}
        foreach(var node in codes){if(node is not JsonValue code||!code.TryGetValue<string>(out var text)||text.Length==0)throw new ProcessingException("BINDING_CODES_INVALID");JsonObject result;
            if(S(set,"source","local")=="external"){var request=new JsonObject{["system"]=set["system"]!.DeepClone(),["code"]=text,["valueSet"]=set["canonical"]!.DeepClone(),["version"]=set["version"]!.DeepClone()};if(set["code_system_version"] is not null)request["codeSystemVersion"]=set["code_system_version"]!.DeepClone();result=await external("terminology_validate_code",request,cancellation);}
            else{var concept=(set["concepts"] as JsonArray??[]).OfType<JsonObject>().FirstOrDefault(c=>S(c,"code")==text);result=new JsonObject{["status"]="VALIDATED",["valid"]=concept is not null&&concept["inactive"]?.GetValue<bool>()!=true&&concept["abstract"]?.GetValue<bool>()!=true,["concept"]=concept?.DeepClone(),["provider"]="local",["scope"]="local_value_set",["system"]=set["system"]!.DeepClone(),["code"]=text,["version"]=set["code_system_version"]?.DeepClone(),["value_set_version"]=set["version"]!.DeepClone()};}
            if(S(result,"status")!="VALIDATED")notExecuted=true;else if(result["valid"]?.GetValue<bool>()!=true)errors.Add("CODE_NOT_VALID_IN_VALUE_SET: "+text);results.Add(result);
        }
        return new JsonObject{["binding"]=binding["id"]!.DeepClone(),["status"]=notExecuted?"NOT_EXECUTED":errors.Count==0?"PARTIAL":"INVALID",["valid"]=errors.Count==0?null:JsonValue.Create(false),["terminology_valid"]=notExecuted?null:JsonValue.Create(errors.Count==0),["target_locations"]=targets,["codes_checked"]=codes.Count,["value_set_version"]=set["version"]!.DeepClone(),["content_sha256"]=Data.Hash(model),["results"]=results,["errors"]=errors,["warnings"]=new JsonArray("Binding strength is platform policy, not native openEHR syntax.","Explicit path presence does not resolve inherited nodes or verify native binding preservation."),["validated_at"]=DateTimeOffset.UtcNow.ToString("O")};
    }
